const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry: Orlando, FL (TIGER/2018/Places), fallback to 30 km buffer around downtown.
  let aoiSource = 'TIGER/2018/Places';
  let places = ee.FeatureCollection('TIGER/2018/Places')
    .filter(ee.Filter.and(ee.Filter.eq('NAME', 'Orlando'), ee.Filter.eq('STATEFP', '12')));
  let placesCount = await places.size().getInfo();
  let aoi;
  if (placesCount > 0) {
    aoi = ee.Feature(places.first()).geometry();
  } else {
    aoiSource = 'Fallback point buffer (30 km)';
    aoi = ee.Geometry.Point([-81.379234, 28.538336]).buffer(30000).bounds();
  }
  aoi = aoi.buffer(0);

  // 2. Acquire GHSL Built dataset bands for 1975 (proxy for 1973) and 2014.
  async function tryImageBands(dsId) {
    try {
      const img = ee.Image(dsId);
      const bands = await img.bandNames().getInfo();
      if (!bands || bands.length === 0) return null;
      const findYearBand = (year) => {
        const y = String(year);
        let cand = bands.find((b) => String(b).toLowerCase().indexOf(y) !== -1);
        if (!cand) {
          // common explicit names
          const opts = ['built_' + y, 'BUILT_' + y, 'ghs_built_' + y];
          cand = bands.find((b) => opts.indexOf(String(b)) !== -1);
        }
        return cand;
      };
      const b75 = findYearBand(1975);
      const b14 = findYearBand(2014);
      if (b75 && b14) {
        return { img: img, b75: b75, b14: b14, dsId: dsId, type: 'image' };
      }
      return null;
    } catch (e) {
      return null;
    }
  }
  async function tryCollection(dsId) {
    try {
      const col = ee.ImageCollection(dsId);
      const size = await col.size().getInfo();
      if (!size || size === 0) return null;
      let img75 = null, img14 = null;

      // Try metadata properties
      for (const prop of ['year', 'YEAR', 'epoch', 'EPOCH']) {
        try {
          const c75 = col.filter(ee.Filter.eq(prop, 1975));
          const c14 = col.filter(ee.Filter.eq(prop, 2014));
          const s75 = await c75.size().getInfo();
          const s14 = await c14.size().getInfo();
          if (s75 > 0 && s14 > 0) {
            img75 = ee.Image(c75.first());
            img14 = ee.Image(c14.first());
            break;
          }
        } catch (e) {}
      }

      // Try system:index string search
      if (!img75 || !img14) {
        let idxs = [];
        try { idxs = await col.aggregate_array('system:index').getInfo(); } catch (e) {}
        if (idxs && idxs.length > 0) {
          const id75 = idxs.find((x) => String(x).indexOf('1975') !== -1);
          const id14 = idxs.find((x) => String(x).indexOf('2014') !== -1);
          if (id75) img75 = ee.Image(col.filter(ee.Filter.eq('system:index', id75)).first());
          if (id14) img14 = ee.Image(col.filter(ee.Filter.eq('system:index', id14)).first());
        }
      }

      if (img75 && img14) {
        const bn75 = await img75.bandNames().getInfo();
        const band = bn75 && bn75.length ? bn75[0] : null;
        if (!band) return null;
        return { img75: img75.select([band]), img14: img14.select([band]), dsId: dsId, type: 'collection', band: band };
      }
      return null;
    } catch (e) {
      return null;
    }
  }

  const dsCandidates = [
    'JRC/GHSL/P2016/BUILT_LDSMT_GLOBE_V1',
    'JRC/GHSL/P2018A/BUILT_LDSMT_GLOBE_V1'
  ];

  let built1975 = null, built2014 = null, dsUsed = null, metaNote = 'Using 1975 as proxy for 1973 (GHSL epochs: 1975, 1990, 2000, 2014).';
  for (const dsId of dsCandidates) {
    const resImg = await tryImageBands(dsId);
    if (resImg) {
      built1975 = resImg.img.select([resImg.b75]);
      built2014 = resImg.img.select([resImg.b14]);
      dsUsed = `${resImg.dsId} bands:${resImg.b75},${resImg.b14}`;
      break;
    }
    const resCol = await tryCollection(dsId);
    if (resCol) {
      built1975 = resCol.img75;
      built2014 = resCol.img14;
      dsUsed = `${resCol.dsId} band:${resCol.band}`;
      break;
    }
  }

  if (!built1975 || !built2014) {
    console.log(`AOI Source: ${aoiSource}`);
    console.log('Dataset: GHSL built-up not found or incompatible.');
    console.log('Result: Unable to locate required years (1975, 2014).');
    console.log('D');
    return;
  }

  // 3. Compute built-up area within AOI
  // Determine whether values are 0..100 or 0..1
  async function computeBuiltArea(img) {
    const band = await img.bandNames().get(0).getInfo();
    const stats = await img.reduceRegion({
      reducer: ee.Reducer.minMax().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    if (!stats || stats[`${band}_count`] === undefined) return { count: 0, area: null, divisor: null };
    const count = stats[`${band}_count`] || 0;
    if (count === 0) return { count: 0, area: null, divisor: null };

    const maxVal = stats[`${band}_max`];
    const divisor = (maxVal !== null && maxVal !== undefined && maxVal > 1) ? 100 : 1;

    const areaKm2 = ee.Image.pixelArea().divide(1e6).rename('area_km2');
    const builtFrac = img.divide(divisor);
    const builtAreaImg = areaKm2.multiply(builtFrac).rename('built_km2');
    const res = await builtAreaImg.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const area = res ? res['built_km2'] : null;
    return { count, area, divisor };
  }

  const aoiAreaKm2 = await ee.Image.pixelArea().divide(1e6).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('area').getInfo();

  const r1975 = await computeBuiltArea(built1975);
  const r2014 = await computeBuiltArea(built2014);

  // 4. Validation and decision
  console.log(`AOI Source: ${aoiSource}, Area_km2: ${aoiAreaKm2 ? aoiAreaKm2.toFixed(1) : 'NA'}`);
  console.log(`Dataset: ${dsUsed}`);
  console.log(metaNote);

  if (r1975.count === 0 || r2014.count === 0) {
    console.log(`1975 Pixels: ${r1975.count}, 2014 Pixels: ${r2014.count}`);
    console.log('C2');
    return;
  }
  if (r1975.area === null || r2014.area === null || isNaN(r1975.area) || isNaN(r2014.area)) {
    console.log('Calculation failed (area is null/NaN).');
    console.log('C3');
    return;
  }

  const delta = r2014.area - r1975.area;
  const ratio = (r1975.area > 0) ? (r2014.area / r1975.area) : null;
  console.log(`1975 Pixels: ${r1975.count}, Built_km2: ${r1975.area.toFixed(2)}`);
  console.log(`2014 Pixels: ${r2014.count}, Built_km2: ${r2014.area.toFixed(2)}`);
  console.log(`Δ Built_km2: ${delta.toFixed(2)}, Ratio(2014/1975): ${ratio ? ratio.toFixed(2) : 'NA'}`);

  if (!isFinite(delta) || (ratio !== null && !isFinite(ratio))) {
    console.log('C3');
    return;
  }

  if (delta > 0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
